library(readr)
library(dplyr)

load_tab <- function(f){
  read_delim(paste0('data/input/',f), delim='\\t', col_types = cols(.default='c'))
}

wf1 <- load_tab('wave_one_lsype_young_person_2020.tab')
wf4 <- load_tab('wave_four_lsype_young_person_2020.tab')
wf6 <- load_tab('wave_six_lsype_young_person_2020.tab')
wf7 <- load_tab('wave_seven_lsype_young_person_2020.tab')
wf8 <- load_tab('ns8_2015_main_interview.tab')
wf9 <- load_tab('ns9_2022_main_interview.tab')

full <- wf1 %>%
  full_join(wf4, by='NSID') %>%
  full_join(wf6, by='NSID') %>%
  full_join(wf7, by='NSID') %>%
  full_join(wf8, by='NSID') %>%
  full_join(wf9, by='NSID')

full <- full %>%
  mutate(
    w4saim = as.numeric(w4saim),
    W6Saim = as.numeric(W6Saim),
    W7SAim = as.numeric(W7SAim)
  )

educaim17 <- full %>%
  mutate(educaim17 = case_when(
    w4saim == 9 ~ 1L,
    w4saim == 5 ~ 2L,
    w4saim == 1 ~ 3L,
    w4saim == 6 ~ 4L,
    w4saim == 4 ~ 5L,
    TRUE ~ NA_integer_
  )) %>% pull(educaim17)

educaim19 <- full %>%
  mutate(educaim19 = case_when(
    W6Saim == 12 ~ 1L,
    W6Saim == 9 ~ 2L,
    W6Saim == 5 ~ 3L,
    W6Saim == 3 ~ 4L,
    W6Saim == 1 ~ 5L,
    TRUE ~ NA_integer_
  )) %>% pull(educaim19)

educaim20 <- full %>%
  mutate(educaim20 = case_when(
    W7SAim == 1 ~ 1L,
    W7SAim == 3 ~ 2L,
    W7SAim == 6 ~ 3L,
    W7SAim == 10 ~ 4L,
    W7SAim == 13 ~ 5L,
    TRUE ~ NA_integer_
  )) %>% pull(educaim20)

educaim25 <- apply(full, 1, function(r){
  if(r['W8ACQUC0J'] == '1' || r['W8VCQUC0J'] == '1') return(5L)
  if(r['W8ACQUC0E'] == '1' || r['W8VCQUC0E'] == '1') return(4L)
  if(r['W8ACQUC0C'] == '1' || r['W8VCQUC0C'] == '1') return(3L)
  if(r['W8ACQUC0B'] == '1' || r['W8VCQUC0B'] == '1') return(2L)
  if(r['W8ACQUC0A'] == '1' || r['W8VCQUC0A'] == '1') return(1L)
  return(-3)
})

educaim32 <- apply(full, 1, function(r){
  if(r['W9ACQUC0J'] == '1' || r['W9VCQUC0J'] == '1') return(5L)
  if(r['W9ACQUC0E'] == '1' || r['W9VCQUC0E'] == '1') return(4L)
  if(r['W9ACQUC0C'] == '1' || r['W9VCQUC0C'] == '1') return(3L)
  if(r['W9ACQUC0B'] == '1' || r['W9VCQUC0B'] == '1') return(2L)
  if(r['W9ACQUC0A'] == '1' || r['W9VCQUC0A'] == '1') return(1L)
  return(-3)
})

final <- full %>%
  select(NSID) %>%
  mutate(
    educaim17 = ifelse(is.na(educaim17), -3, educaim17),
    educaim19 = ifelse(is.na(educaim19), -3, educaim19),
    educaim20 = ifelse(is.na(educaim20), -3, educaim20),
    educaim25 = ifelse(is.na(educaim25), -3, educaim25),
    educaim32 = ifelse(is.na(educaim32), -3, educaim32)
  )

write_csv(final, 'data/output/cleaned_data.csv')

